class Solution {
public:
    long long minimumCost(string s,string t,int flipCost,int swapCost,int crossCost) {
        long long a=0,b=0;
        for(int i=0;i<(int)s.size();i++)if(s[i]!=t[i]){
            if(s[i]=='0')a++;else b++;
        }
        long long p=min(a,b);
        long long ans=p*min(1LL*swapCost,2LL*flipCost);
        long long r=max(a,b)-p;
        ans+=(r/2)*min(1LL*swapCost+crossCost,2LL*flipCost);
        ans+=(r%2)*flipCost;
        return ans;
    }
};
